from itertools import combinations

# Construction from ILP
red = {(0,4),(0,7),(0,8),(1,4),(1,7),(1,8),(2,3),(2,4),(2,6),(2,7),
       (3,5),(3,8),(4,5),(5,6),(5,7),(6,8)}
blue = {(0,2),(0,3),(0,5),(0,6),(1,2),(1,3),(1,5),(1,6),(2,8),(3,4),
        (3,7),(4,6),(4,8),(5,8),(6,7),(7,8)}
uncolored = {(0,1),(2,5),(3,6),(4,7)}

# Normalize edges
def norm(e): return (min(e), max(e))
red = {norm(e) for e in red}
blue = {norm(e) for e in blue}
uncolored = {norm(e) for e in uncolored}

all_edges = set(combinations(range(9), 2))
assert red | blue | uncolored == all_edges
assert red & blue == set()
assert red & uncolored == set()
assert blue & uncolored == set()
print(f"Red: {len(red)}, Blue: {len(blue)}, Uncolored: {len(uncolored)}, Total: {len(red)+len(blue)+len(uncolored)}")

# Check no monochromatic triangle
mono_found = False
for t in combinations(range(9), 3):
    e1, e2, e3 = (t[0],t[1]), (t[1],t[2]), (t[0],t[2])
    if e1 in red and e2 in red and e3 in red:
        print(f"RED TRIANGLE: {t}")
        mono_found = True
    if e1 in blue and e2 in blue and e3 in blue:
        print(f"BLUE TRIANGLE: {t}")
        mono_found = True
if not mono_found:
    print("No monochromatic triangle found. Construction VALID.")

# Analyze structure: group vertices by uncolored pairs
# Uncolored: (0,1), (2,5), (3,6), (4,7), singleton 8
pairs = [(0,1), (2,5), (3,6), (4,7)]
singleton = 8

print("\n--- Structure analysis ---")
# Check: do paired vertices have identical colored neighborhoods?
for a, b in pairs:
    na_red = {v for (u,v) in red if u==a} | {u for (u,v) in red if v==a}
    nb_red = {v for (u,v) in red if u==b} | {u for (u,v) in red if v==b}
    na_blue = {v for (u,v) in blue if u==a} | {u for (u,v) in blue if v==a}
    nb_blue = {v for (u,v) in blue if u==b} | {u for (u,v) in blue if v==b}
    na_red.discard(b); nb_red.discard(a)
    na_blue.discard(b); nb_blue.discard(a)
    print(f"Pair ({a},{b}): red nbrs {na_red} vs {nb_red}, blue nbrs {na_blue} vs {nb_blue}")
    print(f"  Same red? {na_red==nb_red}, Same blue? {na_blue==nb_blue}")

# Group-level adjacency
groups = {'A': (0,1), 'B': (2,5), 'C': (3,6), 'D': (4,7), 'E': (8,)}
def group_red(g1, g2):
    a = groups[g1][0]; b = groups[g2][0]
    if g1 == g2: return None
    return (a,b) in red or (a, groups[g2][1]) in red if len(groups[g2])>1 else (a,b) in red

print("\n--- Group-level red adjacency ---")
for g1 in groups:
    for g2 in groups:
        if g1 < g2:
            a = groups[g1][0]; b = groups[g2][0]
            r = (a,b) in red
            print(f"  {g1}-{g2}: red={r}")

print("\n--- Group-level blue adjacency ---")
for g1 in groups:
    for g2 in groups:
        if g1 < g2:
            a = groups[g1][0]; b = groups[g2][0]
            bl = (a,b) in blue
            print(f"  {g1}-{g2}: blue={bl}")
